INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-04', 'PRJ-LUMPINI', '23 ก.ย. 2569 10:04', 'แชทนี้จะพูดถึงงานที่ ศนท ลุมพินี ทั้งหมด เอกสารและไฟล์งานเริ่มทยอยเอาเข้ามาในระบบแล้วนะ', 0, 0, 'เฮียนัท (Natt)', 'assets/lumpini/line_chat_project_start_files.png', 'assets/lumpini/line_chat_project_start_files.png', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-05', 'PRJ-LUMPINI', '23 ก.ย. 2569 10:14', 'ไปอ่านแชท คำนวณราคารวมทั้งหมด เอาข้อมูลทั้งหมดในแชทนั้นมาใส่ในนี้', 0, 0, 'เฮียนัท (Natt)', NULL, NULL, 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-06', 'PRJ-LUMPINI', '23 ก.ย. 2569 11:05', 'ส่งข้อมูลวัดพื้นที่จริงหน้างานโซนห้องน้ำ อาคารบริการสระว่ายน้ำ เทียบกับ ปร.4 ครับ: รื้อถอนกำแพงเดิม/กระจก 85.9 ตร.ม., ก่ออิฐมวลเบา 127.5 ตร.ม. (ห้องน้ำ 90 + อาบน้ำกลางแจ้ง 37.5), ปูกระเบื้อง 129.5 ตร.ม., ทาสีภายนอก 197.5 ตร.ม.', 0, 0, 'แก๊ป (วิศวกร)', NULL, NULL, 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-07', 'PRJ-LUMPINI', '23 ก.ย. 2569 11:15', 'ตรวจสอบใบเสนอราคา (Quotation เลขที่ 1 วันที่ 21/9/2569) จาก ผรม. นายธนวัฒน์ ชัยมงคล เทียบกับเล่มราคากลาง BOQ (ปร.4) เลขที่ 69039279429 มีจุดที่ราคาเกินงบอยู่ครับ', 0, 0, 'แก๊ป (วิศวกร)', NULL, NULL, 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-08', 'PRJ-LUMPINI', '23 ก.ย. 2569 11:20', 'งานทับหลังคิดเป็นเมตรหนิ ช่างเอา 70 บาทไปคูณพื้นที่ผนังทั้งผืน 127.5 ตร.ม. กลายเป็น 8,925 บาทได้ไง อันนี้คิดซ้ำซ้อนชัดเจน ต้องคิดตามเมตรยาวจริงแค่ประมาณ 40 เมตร ตกแค่ 3,200 บาท ให้ไปเจรจาต่อรองตัดออกด่วน', 0, 0, 'เฮียนัท (Natt)', NULL, NULL, 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-09', 'PRJ-LUMPINI', '30 ก.ย. 2569 10:02', 'ตอนนี้โซนห้องน้ำที่อยู่ข้างสระว่ายน้ำ ทุบรื้อออกหมดแล้วครับ เตรียมวางแนวท่อชักโครก 7 จุด ท่อน้ำเสีย และท่อน้ำดี แต่ยังไม่รู้ว่าจะวางจุดไหนและต่อท่อน้ำดีจุดไหน ขอแปลนระยะด่วนครับ', 0, 0, 'ช่างหนุ่ม', 'assets/lumpini/line_chat_toilet_demo.jpg', 'assets/lumpini/line_chat_toilet_demo.jpg', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-10', 'PRJ-LUMPINI', '30 ก.ย. 2569 10:25', 'วิเคราะห์ระยะอาคารจากแบบสถาปัตย์ กริด 3-4 ระยะ 2.50 ม., กริด 4-5 ระยะ 5.00 ม., กริด 5-7 ระยะ 2.50 ม. กำลังร่างระยะตำแหน่งท่อลงแบบครับ', 0, 0, 'แก๊ป (วิศวกร)', 'assets/lumpini/line_chat_toilet_dimension_check1.png', 'assets/lumpini/line_chat_toilet_dimension_check1.png', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-11', 'PRJ-LUMPINI', '30 ก.ย. 2569 11:19', 'ทำไมระยะที่คุณวาดมา มันไม่ตรงกับในแบบจริง มันเยื้องกันไปหมด แล้วแบบที่ให้มา ขอระยะจริงด้วย ว่าต้องวางท่อตรงไหน ระยะเท่าไหร่', 0, 0, 'เฮียนัท (Natt)', 'assets/lumpini/line_chat_toilet_dimension_check2.png', 'assets/lumpini/line_chat_toilet_dimension_check2.png', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
