INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-13', 'PRJ-LUMPINI', '30 ก.ย. 2569 12:35', 'ที่วงสีฟ้า พื้นจะยกระดับสูงไว้ประมาณ +20 ซม. จากพื้นสีแดง สีฟ้าจะไม่เทคอนกรีตเพิ่ม จะเทคอนกรีตเพิ่มเฉพาะสีแดง ส่วนที่วงสีดำ คือตำแหน่งส้วมเดิม ตำแหน่งใหม่ไม่ได้วางจุดเดิม แต่จะต่อเข้ากับจุดเดิม ทำสโลปให้ดี', 0, 0, 'เฮียนัท (Natt)', 'assets/lumpini/line_chat_toilet_floor_elevation_20cm.png', 'assets/lumpini/line_chat_toilet_floor_elevation_20cm.png', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
