INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-22', 'PRJ-LUMPINI', '05 ต.ค. 2569 10:10', 'ตรวจสอบเปรียบเทียบกับ ปร.4 กทม. แล้วตรง 100% ครับ สรุปใช้ท่อ PVC สีฟ้า มอก. ชั้น 8.5 ตราช้าง SCG ท่อ 4 นิ้ว 5 เส้น, สามทางวาย 45 องศา 7 ตัว, ข้องอ 45 องศา 14 ตัว, ท่อ 2 นิ้ว 4 เส้น, Floor Drain 8 จุด, กาวทาท่อ SCG 1 กระป๋องใหญ่', 0, 0, 'แก๊ป (วิศวกร)', 'assets/lumpini/line_chat_sanitary_pipe_order_check.png', 'assets/lumpini/line_chat_sanitary_pipe_order_check.png', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
