INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-25', 'PRJ-LUMPINI', '06 ต.ค. 2569 20:56', 'ข้างสระว่ายน้ำ หลังจากแย็กทรายล้างออก พื้นผิวคอนกรีตเดิมเป็นหลุมเป็นบ่อมากครับ ถ้าจะทำพื้นยาง EPDM ทับไป กลัวน้ำขังหลุมทำให้อายุไม่ถึง 2 ปี ต้องแก้ไขยังไงครับ', 0, 0, 'ช่างหน้างาน', 'assets/lumpini/line_chat_pool_deck_screed.jpg', 'assets/lumpini/line_chat_pool_deck_screed.jpg', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-26', 'PRJ-LUMPINI', '06 ต.ค. 2569 21:05', 'ห้ามเทปูนทับพื้นแห้งๆ เด็ดขาด! ให้ช่างทำน้ำแป้งกาวรองพื้น Slurry: ผสมน้ำยา SikaLatex กับน้ำสะอาด (1:1) ใส่ปูนช้างแดง 2 พลั่ว กวนให้เป็นน้ำแป้งสีเทา ทาลงพื้น แล้วปาดปูนทรายมอร์ต้า (ปูนช้างแดง 1 ส่วน : ทรายหยาบ 2.5 ส่วน ผสมน้ำ SikaLatex 1:3) ทับทันทีแบบเปียกชนเปียก (Wet-on-Wet) หนา 1-2 ซม. สโลป 1% ลงรางน้ำล้น ส่วนท้องพื้นเพดานที่กะเทาะให้ใช้ Sikadur-32 TH ทาประสาน', 0, 0, 'เฮียนัท (Natt)', 'assets/lumpini/sika_repair_214616.jpg', 'assets/lumpini/sika_repair_214616.jpg', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-27', 'PRJ-LUMPINI', '12 ต.ค. 2569 09:48', 'งานวงกบและประตูไม้อัดยาง ศนท ลุมพินี เสนอ: วงกบไม้เต็ง 80x190 ซม. 4 ชุด (2"x4" วัดจริง 4.5x9.5 ซม.) + วงกบ 160x190 ซม. 1 ชุด พร้อมบานประตูไม้อัดยางกาวทนน้ำ มอก. หนา 35 มม. 6 บาน ทำใบขออนุมัติ MAR-BLC-LMP-001 สั้นๆ ส่ง กทม. เลย', 0, 0, 'เฮียนัท (Natt)', NULL, NULL, 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-28', 'PRJ-LUMPINI', '12 ต.ค. 2569 11:15', 'จัดทำเอกสารขออนุมัติวัสดุ MAR-BLC-LMP-001 วงกบไม้เต็ง 5 ชุด และประตูไม้อัดยาง 6 บาน ส่งผู้ควบคุมงาน กทม. เรียบร้อยครับ', 0, 0, 'แก๊ป (วิศวกร)', NULL, NULL, 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-29', 'PRJ-LUMPINI', '15 ต.ค. 2569 11:47', 'ตอนนี้จะต้องทำงานก่อฉาบแล้ว ขอสั่งอิฐมวลเบา 90 ตร.ม. (หนา 7.5 ซม.) ปูนฉาบ 180 ตร.ม. แต่ข้อ 2 ไม่เอาเหล็กหนวดกุ้ง/แผ่นยึดเสานะครับ', 0, 0, 'ช่างหนุ่ม', 'assets/lumpini/line_chat_aac_block_order_no_straps.png', 'assets/lumpini/line_chat_aac_block_order_no_straps.png', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-30', 'PRJ-LUMPINI', '15 ต.ค. 2569 14:49', 'ช่างบอกว่าจะเอาเหล็กเส้นเก่าจากการรื้อถอนมาตัดทำหนวดกุ้งเจาะเสียบเสาเดิม ถือว่าช่วยประหยัดเงินดีมาก แต่เตือนช่างด้วยว่า ต้องบากร่องหลังอิฐมวลเบาด้วย ไม่งั้นเหล็ก 2-3 หุนจะดันให้อิฐกระดกไม่ได้ระดับ และต้องขึงตาข่ายกรงไก่กันร้าวด้วย', 0, 0, 'เฮียนัท (Natt)', NULL, NULL, 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-31', 'PRJ-LUMPINI', '15 ต.ค. 2569 14:58', 'ส่งใบเสนอราคาค่าแรงงานปรับปรุงอาคารและห้องน้ำ 9 รายการ (รื้อถอน, ฉาบใน 113.2 ตร.ม., ฉาบนอก 103.8 ตร.ม., เททับหลัง 41.9 ม., ก่ออิฐมวลเบา 90 ตร.ม., เทปูน 44 ตร.ม., ฝ้า 90 ตร.ม., ปูกระเบื้องผนัง 113.2 ตร.ม., ปูกระเบื้องพื้น 90 ตร.ม.) รวมเป็นเงิน 153,745 บาทครับ', 0, 0, 'ช่างหนุ่ม', 'assets/lumpini/quote_chang_noom_153745.jpg', 'assets/lumpini/quote_chang_noom_153745.jpg', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-32', 'PRJ-LUMPINI', '15 ต.ค. 2569 15:48', 'ตกลงค่าแรงช่างหนุ่มตามใบเสนอราคานี้ 153,745 บาท ส่วนตาข่ายกรงไก่ เลือกรายการที่ 4 ''ลวดตาข่ายหกเหลี่ยม 4 หุน (ม้วน 90ซม.*30ม.)'' เม็ดทรายแทรกผ่านแน่นหนา ไม่เด้งสปริงตัว ดีที่สุดสำหรับงานฉาบปูนกันร้าว', 0, 0, 'เฮียนัท (Natt)', 'assets/lumpini/line_chat_hex_wire_mesh_choice.png', 'assets/lumpini/line_chat_hex_wire_mesh_choice.png', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-33', 'PRJ-LUMPINI', '16 ต.ค. 2569 10:43', 'เปรียบเทียบใบเสนอราคาวัสดุก่อฉาบ: ร้านพรวัฒนา (Q-CON 7.5 ซม. 800 ก้อน @24.50 + ปูนฉาบ XPERT 85 ถุง @98 + ปูนก่อ 25 ถุง รวม 27,930 บ.) ถูกกว่าร้าน ภ.ทวีวรรณ ถึง 1,200 บาท แถมได้แบรนด์ Q-CON SCG สั่งร้านพรวัฒนาทันที', 0, 0, 'เฮียนัท (Natt)', 'assets/lumpini/line_chat_pornwatana_aac_order.png', 'assets/lumpini/line_chat_pornwatana_aac_order.png', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
