INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-36', 'PRJ-LUMPINI', '27 ต.ค. 2569 09:02', 'ลองดูผังเดินท่อน้ำดี Version 2 และ Version 3 ท่อที่ต้องต่อไปที่อุปกรณ์ส่วนล่างในห้องน้ำทั้งสองห้อง ทำเป็นสามทางแยกจากเมน เข้าไปที่อุปกรณ์ข้างล่างทั้งหมดเลย ไม่ต้องแยก ช ญ ดีมั้ย แนะนำหน่อย', 0, 0, 'เฮียนัท (Natt)', 'assets/lumpini/line_chat_water_pipe_v3_concept.png', 'assets/lumpini/line_chat_water_pipe_v3_concept.png', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-37', 'PRJ-LUMPINI', '27 ต.ค. 2569 09:17', 'ถ้าแยกเป็น 4 เส้นแบบนี้ล่ะ: ต่อแยกจากเมน 1 นิ้วออกเป็น 4 สายอิสระ (ชายบน, ชายล่าง, หญิงบน, หญิงล่าง) ท่อ 4 หุน ถ้ามีปัญหาต้องซ่อม ก็ไปปิดที่เมนวาล์วตัวเดียวเลย น้ำจะไม่ไหลไปทั้งสองห้อง เอาแบบนี้แหละ วาดมาเลย พร้อมจำนวนของที่ต้องสั่ง', 0, 0, 'เฮียนัท (Natt)', 'assets/lumpini/water_pipe_v3_4lines.png', 'assets/lumpini/water_pipe_v3_4lines.png', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
