INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-40', 'PRJ-LUMPINI', '30 ต.ค. 2569 11:12', 'ใบขออนุมัติกระเบื้องผนังไม่ต้องไปใส่ราคาซื้อหรือราคากลาง เดี๋ยว กทม. รู้ต้นทุนเราหมด ให้ใส่เฉพาะสเปกทางวิศวกรรม มาตรฐาน มอก. และผลทดสอบเท่านั้น แก้ไขด่วน', 0, 0, 'เฮียนัท (Natt)', 'assets/lumpini/line_chat_duragres_tile_submittal_fix.png', 'assets/lumpini/line_chat_duragres_tile_submittal_fix.png', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
