INSERT INTO daily_logs (id, project_id, log_date, summary, area_sqm_done, worker_count, sender_name, photo_url, local_photo_path, category, synced_to_pc, created_at) VALUES ('MSG-LMP-43', 'PRJ-LUMPINI', '03 พ.ย. 2569 13:18', 'สรุปผังติดตั้งไฟ BLC-LMP-MAT-003 V.2 เสร็จเรียบร้อย: โคมดาวน์ไลท์ CARINI + หลอด LED HITEK 40 จุด (ห้องน้ำ 38 จุด + ห้องติดต่อ-สอบถาม 2 จุด) และโคมตะแกรง FL 8 ชุด ถูกต้องตาม drawing และ BOQ ลำดับ 109-110', 0, 0, 'เฮียนัท (Natt)', 'assets/lumpini/lighting_plan_40points_v2.png', 'assets/lumpini/lighting_plan_40points_v2.png', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
